let a: Option<i32> = Some(3);
let b: Option<i32> = None;
println!("{} {}", a.unwrap_or(0), b.unwrap_or(0));

fn parse(s: &str) -> Result<i32, std::num::ParseIntError> {
    s.parse::<i32>()
}
match parse("42") {
    Ok(n) => println!("{}", n),
    Err(e) => println!("{}", e),
}

let mut v = vec![1, 2, 3];
v.push(4);
println!("{} {}", v.len(), v[0]);

let mut s = String::from("안녕");
s.push_str(" 세상");
println!("{}", s);

use std::collections::HashMap;
let mut m = HashMap::new();
m.insert("가온", 20);
println!("{:?}", m.get("가온"));

let s: &str = "hello";
let part = &s[0..2];
println!("{}", part);

let n: i32 = -5;
let u: u8 = 255;
println!("{} {}", n, u);
